GENERAL=[('🎵', 'MUZIKA IR ĮRANGA', 'Jei treniruojatės savarankiškai, muzikos aparatūrą įjunkite patys. Baigę treniruotę, muziką ir visą naudotą aparatūrą išjunkite.'), ('💡', 'APŠVIETIMAS', 'Apšvietimą naudokite pagal poreikį. Išeidami iš patalpų išjunkite visą apšvietimą, įskaitant spalvotą LED apšvietimą ir dekoratyvinius šviestuvus.'), ('❄️', 'KLIMATO KONTROLĖ', 'Jei reikia, reguliuokite radiatorius ar oro kondicionierių naudodami tam skirtus valdiklius. Išeidami būtinai išjunkite oro kondicionierių ir kitus naudotus klimato kontrolės įrenginius.'), ('🚪', 'IŠĖJIMAS IŠ PATALPŲ', 'Jei išeinate paskutiniai, įsitikinkite, kad patalpose neliko kitų žmonių. Patikrinkite sales, koridorių, tualetus ir kitas bendras erdves.')]
POLE=dict(file="RAI_Academy_Pole_Sport_erdves_taisykles_A3.pdf",sub="POLE SPORT ERDVĖS TAISYKLĖS",
 left=[("PASIRUOŠIMAS IR HIGIENA",[('👕', 'APRANGA', 'Dėvėkite pole sportui tinkamą aprangą, pavyzdžiui, šortus ir marškinėlius be rankovių arba sportinę liemenėlę. Pole sportui reikalingas odos kontaktas su stulpu, todėl apranga turi leisti atidengti reikiamas kūno vietas.'), ('🧴', 'HIGIENA IR KŪNO PRIEŽIŪRA', 'Treniruotės dieną venkite kūno kremų, losjonų, aliejų ir kitų riebių priemonių. Jos mažina sukibimą su stulpu, gali padaryti treniruotę nesaugią ir palikti sunkiai pašalinamus pėdsakus ant jo paviršiaus.'), ('💍', 'PAPUOŠALAI', 'Prieš treniruotę nusiimkite visus papuošalus: žiedus, apyrankes, laikrodžius, vėrinius ir auskarus. Papuošalai gali sužeisti jus, subraižyti stulpų paviršių ar sugadinti inventorių.'), ('🧽', 'STULPŲ VALYMAS', 'Stulpą nuvalykite prieš treniruotę ir po jos. Naudokite studijoje esantį stulpų valiklį ir savo atsineštą mikropluošto rankšluostį.')],1)],
 right=[("SAUGUMAS IR INVENTORIUS",[('🔧', 'STULPO PATIKRA', 'Prieš pradėdami treniruotę patikrinkite stulpo stabilumą ir režimą – ar jis nustatytas suktis, ar veikti statiniu režimu. Prieš naudodami įsitikinkite, kad stulpas tinkamai užfiksuotas.'), ('⚠️', 'INVENTORIUS', 'Studijoje esantį inventorių naudokite tik pagal paskirtį. Pastebėję inventoriaus pažeidimą arba jį sugadinę, nedelsdami informuokite administraciją ar trenerę.'), ('🦶', 'AVALYNĖ', 'Treniruotės paprastai vyksta basomis, nebent konkrečios treniruotės treneris nurodė kitaip.')],2),("PO TRENIRUOTĖS",[('🧹', 'TVARKA', 'Po treniruotės nuvalykite naudotą inventorių ir grąžinkite jį į vietą. Šiukšles išmeskite į tam skirtas šiukšliadėžes. Po savęs palikite švarią ir tvarkingą salę.')],3)])
AIR=dict(file="RAI_Academy_Oro_akrobatikos_erdves_taisykles_A3.pdf",sub="ORO AKROBATIKOS ERDVĖS TAISYKLĖS",
 left=[("PASIRUOŠIMAS",[('👕', 'APRANGA', 'Treniruokitės su aptemptais, neslidžios medžiagos drabužiais, dengiančiais pažastis, liemenį ir kelių linkius. Rekomenduojama dėvėti ilgas kelnes ar tampres ir marškinėlius su rankovėmis. Nenaudokite drabužių su atviromis metalinėmis detalėmis, užtrauktukais ar kitais elementais, galinčiais pažeisti inventorių.'), ('💍', 'PAPUOŠALAI IR HIGIENA', 'Prieš treniruotę nusiimkite visus papuošalus: auskarus, žiedus, grandinėles, apyrankes ir laikrodžius. Prieš treniruotę nusiplaukite rankas, plaukus susiriškite į kuodą arba kasą. Rekomenduojama treniruotis trumpais nagais.'), ('🔥', 'APŠILIMAS', 'Kiekvieną treniruotę pradėkite viso kūno pramankšta. Ypatingą dėmesį skirkite pečių, riešų, nugaros ir klubų apšilimui.')],1),("PO TRENIRUOTĖS",[('🧘', 'ATVĖSIMAS', 'Treniruotę užbaikite tempimo pratimais, ypač skirtais pečiams, nugarai ir rankoms.'), ('🧹', 'TVARKA', 'Po treniruotės visą inventorių grąžinkite į jo vietas ir palikite erdvę tokią, kokią radote. Kopėčias išneškite į rūbinę ir pritvirtinkite joms skirtoje vietoje.'), ('🚨', 'INVENTORIAUS PAŽEIDIMAI', 'Pastebėję inventoriaus pažeidimą arba jį sugadinę, nedelsdami informuokite studiją ar trenerę. Neslėpkite pažeidimų – nuo jų gali priklausyti kitų žmonių saugumas.')],3)],
 right=[("SAUGUMAS IR INVENTORIUS",[('🔧', 'INVENTORIAUS NAUDOJIMAS', 'Inventorių naudokite tik pagal paskirtį. Tvirtinimus, karabinus ir suktukus keisti galima tik treneriui arba jam prižiūrint. Jei treniruotei pakeitėte inventoriaus vietą ar tvirtinimus, būtinai patikrinkite, ar visi sujungimai tinkamai užfiksuoti ir karabinų apsaugos užveržtos.'), ('🪜', 'INVENTORIAUS NULEIDIMAS IR PAKĖLIMAS', 'Juostų ir lankų nuleidimui bei pakėlimui naudokite rūbinėje esančias kopėčias. Po treniruotės nenaudojamą inventorių pakelkite arba pritvirtinkite taip, kad jis netrukdytų kitiems lankytojams.'), ('🛏️', 'ČIUŽINIAI', 'Po juostomis ir lankais visada turi būti paklotas bent vienas čiužinys. Treniruotis be čiužinio draudžiama.'), ('👀', 'SAUGUMAS IR DĖMESYS', 'Treniruotės metu stebėkite aplinką ir laikykitės saugaus atstumo nuo kitų sportuojančiųjų. Nebūkite po naudojamu inventoriumi, nepalikite po juo telefonų, gertuvių ar kitų daiktų.'), ('📏', 'TRENIRUOTĖS AUKŠTIS', 'Pasirinkite savo gebėjimus atitinkantį aukštį. Jei neturite pakankamai patirties, naujus elementus mokykitės ir atlikite kuo arčiau grindų.'), ('⚠️', 'SUDĖTINGI ELEMENTAI', 'Sudėtingus, painius ar didesnės rizikos elementus rekomenduojama atlikti tik tada, kai salėje yra kitas žmogus. Nevertinkite savo galimybių pervertindami jėgas ar patirtį.'), ('⬇️', 'NUSILEIDIMAS', 'Nuo juostų nečiuožkite žemyn – galite nusideginti delnus. Venkite nekontroliuojamų nušokimų. Nuo inventoriaus nusileiskite ramiai ir kontroliuojamai.')],2)])
